draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.fillStyle = '#ccc';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // Draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+120, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+100);
  ctx.lineTo(W/2, H/2+150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+130);
  ctx.lineTo(W/2-30, H/2+160);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+130);
  ctx.lineTo(W/2+30, H/2+160);
  ctx.stroke();

  // Apply wisdom lesson
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Applying wisdom to life', W/2, H/2-80);

  // Life line
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2-70, H/2-30);
  ctx.lineTo(W/2+70, H/2-30);
  ctx.stroke();

  // Bouncing book pages
  ctx.fillStyle = '#ccc';
  ctx.fillRect(W/2-20+20*Math.sin(t), H/2-20, 40, 20);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-20+20*Math.sin(t), H/2-20, 40, 20);

  ctx.restore();
}
